[Form]
public class AVAQuotInventView extends FormRun
{
    SalesQuotationTable     salesQuotationTable;

}

public void init()
{
    super();
    if (this.args() && this.args().dataset() == tableNum(SalesQuotationTable))
    {
        salesQuotationTable = this.args().record();
    }

    if (salesQuotationTable)
    {
        this.iniBOMPos(salesQuotationTable);
    }
}

void iniBOMPos(SalesQuotationTable      _salesQuotationTable)
{
    SalesQuotationLine      sql;
    InventDim               inventDim;
    InventDimParm           inventDimParm;
    InventSum               inventSum;
    BOMVersion              bomV;
    BOM                     bom;
    Qty                     QuotQty, AvailQty, OrderedQty;
    InventDim               bomInventDim;
    InventDimParm           bomInventDimParm;
    InventSum               bomInventSum;
    AVAQuotAvailState       ItemSetState, bomState;


    while select sql order by KCS_QLLVPosition where sql.QuotationId == _salesQuotationTable.QuotationId
    {
        AVAQuotInventView.clear();
        AVAQuotInventView.QuotationId               = _salesQuotationTable.QuotationId;
        AVAQuotInventView.QuotInventSiteId          = _salesQuotationTable.InventSiteId;
        AVAQuotInventView.QuotQty                   = sql.SalesQty;
        AVAQuotInventView.KCS_QLInternalPosition    = sql.KCS_QLInternalPosition;
        AVAQuotInventView.KCS_QLLVPosition          = sql.KCS_QLLVPosition;
        AVAQuotInventView.ItemId                    = sql.ItemId;
        inventDim                                   = sql.inventDim();
        inventDimParm.initFromInventDim(inventDim);
        AVAQuotInventView.ItemInventSiteId          = inventDim.InventSiteId;
        AVAQuotInventView.InventLocationId          = inventDim.InventLocationId;
        inventSum                                   = inventSum::findSum(AVAQuotInventView.ItemId, inventDim, inventDimParm);
        AVAQuotInventView.AvailQty                  = inventSum.AvailPhysical;
        AVAQuotInventView.OrderedQty                = inventSum.OnOrder;
        AVAQuotInventView.QuotAvailState            = (AVAQuotInventView.AvailQty - AVAQuotInventView.OrderedQty) >= AVAQuotInventView.QuotQty ? AVAQuotAvailState::OK : AVAQuotAvailState::notOK;
        //AVAQuotInventView.RevRecBundle              = sql.inventTable().RevRecBundle;
        AVAQuotInventView.IsItemSet                 = sql.inventTable().AVAItemSet;
        if(AVAQuotInventView.IsItemSet)
        {
            ItemSetState = AVAQuotAvailState::OK;
            bomV = BOMVersion::findActive(AVAQuotInventView.ItemId, DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()), AVAQuotInventView.QuotQty, inventDim);
            if(bomV)
            {
                while select bom where bom.BOMId == bomV.BOMId
                {
                    bomInventDim    = inventDim;
                    bomInventDimParm.initFromInventDim(bomInventDim);
                    bomInventSum              = InventSum::findSum(bom.ItemId, bomInventDim, bomInventDimParm);
                    AvailQty                  = bomInventSum.PhysicalInvent - (bomInventSum.ReservPhysical - bomInventSum.Ordered);
                    OrderedQty                = bominventSum.OnOrder;
                    bomState                  = (AvailQty - OrderedQty) >= QuotQty ? AVAQuotAvailState::OK : AVAQuotAvailState::notOK;
                    if (bomState == AVAQuotAvailState::notOK)
                    {
                        ItemSetState = AVAQuotAvailState::notOK;
                    }

                }
            }
        }
        AVAQuotInventView.QuotAvailState = ItemSetState;
        AVAQuotInventView.insert();

        //if(AVAQuotInventView.RevRecBundle)
        if(AVAQuotInventView.IsItemSet)
        {
            bomV = BOMVersion::findActive(AVAQuotInventView.ItemId, DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()), AVAQuotInventView.QuotQty, inventDim);
            if(bomV)
            {
                while select bom where bom.BOMId == bomV.BOMId
                {
                    this.insertBOMPos(bom, inventDim, AVAQuotInventView.QuotQty, AVAQuotInventView.KCS_QLLVPosition, AVAQuotInventView.KCS_QLInternalPosition);
                }
            }
        }
    }
}

void insertBOMPos(BOM _bom, InventDim _inventDim, Qty _bundleQty, KCS_QLLVPosition _lvPos, KCS_QLInternalPosition _intPos)
{
    InventDim       bomInventDim;
    InventDimParm   bomInventDimParm;
    InventSum       bomInventSum;

    AVAQuotInventView.clear();
    AVAQuotInventView.ItemId            = _bom.ItemId;
    AVAQuotInventView.QuotQty           = _bundleQty * _bom.BOMQty / (_bom.BOMQtySerie ? _bom.BOMQtySerie : 1);
    AVAQuotInventView.KCS_QLLVPosition  = _lvPos;
    AVAQuotInventView.KCS_QLInternalPosition    = _intPos;
    //bomInventDim    = InventItemInventSetup::find(AVAQuotInventView.ItemId, _inventDim.inventDimId).inventDimDefault();
    bomInventDim    = _inventDim;
    bomInventDimParm.initFromInventDim(bomInventDim);
    bomInventSum                        = InventSum::findSum(AVAQuotInventView.ItemId, bomInventDim, bomInventDimParm);
    //AVAQuotInventView.AvailQty                  = bominventSum.AvailPhysical;
    AVAQuotInventView.AvailQty                  = bomInventSum.PhysicalInvent - (bomInventSum.ReservPhysical - bomInventSum.Ordered);
    AVAQuotInventView.OrderedQty                = bominventSum.OnOrder;
    AVAQuotInventView.QuotAvailState            = (AVAQuotInventView.AvailQty - AVAQuotInventView.OrderedQty) >= AVAQuotInventView.QuotQty ? AVAQuotAvailState::OK : AVAQuotAvailState::notOK;
    AVAQuotInventView.insert();
}
